"""Typed projection of the canonical Blueprint schema (v1.0.0).

Contract
--------
* The **schema** (``src/forge/schemas/blueprint.schema.json``) is the
  referee — see ADR-0007.
* These models are a **generated projection** of the schema, kept in
  lockstep by ``make models-check`` and a Hypothesis parity test — see
  ADR-0008.
* Hand edits are allowed only inside ``# region: hand-tuned`` blocks.
  Everything else is regenerated verbatim; the sync test fails CI on any
  drift.

Consumers import from ``forge.models`` (the façade), never this module
directly, so the codegen backend can be swapped without touching call
sites.

Strictness model
----------------
The models ingest *parsed YAML*, which produces plain Python strings for
every scalar. Model-wide ``strict=True`` would therefore be a
self-inflicted parity regression: the schema accepts ``"api"`` for a
``Category`` field (both are JSON strings), but a strict enum field
requires an actual ``Category.api`` instance. That is the case the
parity test catches, and this module's configuration is the fix.

The protections that matter are preserved per-field:

* ``extra="forbid"`` — mirrors ``additionalProperties: false``. Unknown
  fields are rejected on every model. Non-negotiable; a model that
  silently accepts unknown fields masks author typos.
* ``frozen=True`` — instances are immutable, so a validated blueprint
  cannot be mutated into an invalid state downstream.
* Numeric bounds on ``timeout`` (``ge=1, le=3600``) reject strings at
  the field level; ``required: bool`` uses Pydantic's lax mode, which
  still rejects ``"yes"``/``"no"`` for a bool field.
* Enum fields accept the canonical *string value* because the schema
  does. The enums subclass ``str`` so downstream code can use them
  interchangeably with the raw wire value.

The augment contract
--------------------
Three augmentations to the generator's output are documented in
``tests/unit/models/test_generated_in_sync.py::_KNOWN_AUGMENTS`` and in
ADR-0008. Every one of them is load-bearing:

1. ``frozen=True`` in each model's ``model_config`` — enforced at
   runtime by ``test_parsed_model_is_immutable``.
2. ``= []`` on the three optional list fields (``variables``, ``files``,
   ``conditional_files``) — mirrors the schema's ``"default": []``,
   which the generator does not emit as a field default.
3. ``class BlueprintMetadata`` — an ergonomic view with no ``$defs``
   entry; the generator cannot produce it from the schema.

Each augment lives inside a ``# region: hand-tuned`` block so
regeneration preserves it. Removing or rewriting one — even to a
"cleaner" form that expresses the same semantics, such as
``Field(default_factory=list)`` — breaks the contract and is caught by
the drift test. That is the point: the augment list, ADR-0008, and the
committed file must all agree, because a divergence in any one of them
means a future reader cannot tell which is authoritative.
"""

from __future__ import annotations

from enum import Enum
from typing import Annotated, Any, Literal

from pydantic import BaseModel, ConfigDict, Field, StringConstraints, model_validator

# ---------------------------------------------------------------------------
# region: hand-tuned — reusable constrained-string aliases
#
# The generator inlines every ``pattern``/``minLength``/``maxLength`` triple
# at the field site, which duplicates long regexes across ``Blueprint``,
# ``BlueprintMetadata``, ``DiscoveredBlueprint``, and any future view. That
# duplication is a technical-debt trap: a schema edit changes one regex and
# reviewers must catch every copy. Centralising the constraints here means
# the generated field definitions *reference* an alias instead of restating
# the pattern, so a schema change propagates through one edit.
#
# Each alias is named after the schema field it mirrors, so a reader can
# grep ``blueprint.schema.json`` for the source of truth in one step.
# ---------------------------------------------------------------------------

SemVer = Annotated[
    str,
    StringConstraints(
        pattern=(
            r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
            r"(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$"
        )
    ),
]

BlueprintId = Annotated[
    str,
    StringConstraints(
        pattern=r"^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)+$",
        min_length=3,
        max_length=128,
    ),
]

VariableId = Annotated[
    str,
    StringConstraints(pattern=r"^[a-z][a-z0-9_]*$", min_length=1, max_length=64),
]

CheckId = Annotated[
    str,
    StringConstraints(pattern=r"^[a-z][a-z0-9_]*$", min_length=1, max_length=64),
]

# ``source`` and ``destination`` share a path-safety constraint in the
# schema: relative, no leading slash, no ``..`` segment. Keeping them as
# one alias makes it obvious that the two fields are governed by the same
# rule — a change to path safety is a one-line edit.
#
# The negative lookahead ``(?!...)`` is the reason ``regex_engine`` is
# set to ``python-re`` on ``_BlueprintModel``: the default engine (Rust
# ``regex``) does not support lookarounds and would silently fail to
# enforce this pattern.
SafeRelativePath = Annotated[
    str,
    StringConstraints(
        pattern=r"^(?!/)(?!.*\.\.(?:/|$)).+$",
        min_length=1,
        max_length=400,
    ),
]
# endregion


# ---------------------------------------------------------------------------
# region: hand-tuned — string-valued enums
#
# All three enums subclass ``str`` so that:
#
# * A field annotated ``Category`` accepts ``"api"`` from parsed YAML
#   (the canonical input). Pydantic's lax mode coerces the string to the
#   enum member, which is exactly what we want — a strict enum field
#   would make every blueprint unloadable.
# * Downstream code can use the member and the raw string interchangeably:
#   ``Category.api == "api"`` is ``True``; ``json.dumps({"c": Category.api})``
#   yields ``{"c": "api"}`` without a custom encoder. Discovery warnings,
#   ``forge list --json`` output, and log fields all rely on this.
# * A future contributor who tries to replace ``Category`` with a plain
#   ``Literal[...]`` has to reckon with the reason it is an Enum (readable
#   ``str(...)``, exhaustiveness in ``match``, ``set(Category)`` for
#   validation) — the docstrings carry that reasoning.
# ---------------------------------------------------------------------------


class Category(str, Enum):
    """Coarse classifier used for grouping in the selector."""

    api = "api"
    automation = "automation"
    frontend = "frontend"
    library = "library"
    cli = "cli"
    other = "other"


class VariableType(str, Enum):
    """Value type.

    ``enum`` requires ``validation.enum``; ``string`` may optionally use
    ``validation.pattern``; ``boolean`` takes no validation block.
    """

    string = "string"
    boolean = "boolean"
    enum = "enum"


class CheckType(str, Enum):
    """Kind of check.

    ``command`` runs a shell command; ``required_file`` asserts a path
    exists.
    """

    command = "command"
    required_file = "required_file"
# endregion


class _BlueprintModel(BaseModel):
    """Shared base for every blueprint model.

    Two guarantees are enforced on every subclass:

    * ``extra="forbid"`` mirrors the schema's
      ``additionalProperties: false``. Unknown fields are rejected so
      author typos surface at parse time rather than being silently
      ignored downstream.
    * ``frozen=True`` makes validated instances immutable. A blueprint
      that passed validation cannot be mutated into an invalid state
      after the fact — the invariant is a property of the object, not
      a discipline callers must remember. This is augment #1 in
      ``_KNOWN_AUGMENTS``; ``test_parsed_model_is_immutable`` checks
      it at runtime.

    ``populate_by_name`` is kept from the generated draft because it
    preserves alias-based access if a future schema revision introduces
    aliases; it has no effect today and does not weaken the config.

    ``regex_engine="python-re"`` is required: ``SafeRelativePath`` uses a
    negative lookahead ``(?!...)``, which the RE2 engine does not
    support. Leaving the default engine would silently disable the path
    safety check.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
        populate_by_name=True,
        regex_engine="python-re",
    )


class Compatibility(_BlueprintModel):
    """Minimum Forge CLI version required to consume this blueprint."""

    min_forge_version: SemVer


